from 写入第二遍 import add
add('22_001',2,'16:9，高位俯视全景，武士与青在画面中央偏下，石面裂纹向四周放射；固定机位，冲击时只短震一次。','武士巨大身体重砸石面，石板从接触中心先沉下去，再一圈圈翘裂；白色冲击形沿石缝向外迸开，大块石体错位抬起，细尘比大块稍晚喷出。青保持牵住腕臂的姿势完成最后一下下拉，随即顺着石面震动屈膝稳住，手指开始松开。','灰绿不规则石铺地面被砸开，深灰裂缝与米灰扬尘呈放射层次；原有外围石面在边缘仍清楚。','上方云天冷白漫射，裂缝内部深暗，白色重音是一瞬冲击替换画。','单次厚重摔地巨响，石板断裂随后成串接上，碎石抬起再落下的声响有先后。',phase='result',node={'武士.阶段':'被摔入碎裂石面','青.阶段':'抡摔完成、开始松手','双方.接触':'双手由锁腕转为松指'},meaning='原作放射状裂地和两人处在冲击中心的结果完整保留，不只用尘雾掩去身体与石体。')
add('22_002',10,'16:9，青居中正面中近景，头到腰上，张开的双手分别留在两侧；固定到大喊后，镜头只向后退半步，落幅仍见她手与肩的同一姿态关系。','青把双手从武士腕上彻底松开，向后退开一步，先低头看掌心，脸上立刻挤出嫌恶；她把两只手张开抬到肩旁，眼睛闭紧、嘴大张，眼角挤出泪点，脸涨红地喊起来。前句结束她抖了抖双手，手指仍张开；后句胸肩向前顶，头却往后缩，喊完再把眼睛睁开，盯向尘中的武士。','铅蓝云天、低处新翻起的米灰尘雾，灰绿石地在下缘窄窄露出。','上方云天冷白柔光，尘层对脸部返中性弱光。','双手甩开时护件短响，脚下碎石被后退鞋底踢开，喘气夹在两个句子之间。',ja=['あああああ！あんたと戦うの、本当に気持ち悪い！！','なんでこんなに湿って、柔らかくて、ベタベタしてるの？！'],tone='嫌恶得带哭腔，第一句爆发，后句质问越说越急，末尾喘气。',kind='mixed',phase='reaction',node={'双方.接触':'青已松手后退、无接触','青.阶段':'嫌恶爆发后重新盯住对手'},card={'opening':'抡摔成功，青才有余裕意识到抓握的触感。','beats':['松手退开，看掌心立刻嫌恶','闭眼大喊、张手甩开','身体前顶而头后缩，喊完重新睁眼'],'coupling':'嫌恶来自刚才抓臂，不把后面的喷流提前沾到她身上。','landing':'手仍离身体，目光回到对手。'})
add('23_001',9,'16:9，青侧面中景位于画面左侧，朝右侧画外武士，腰上到头顶入画；一只手松抬在身后肩旁，镜头沿她的视线缓推，落幅保留侧脸与手的同框关系。','青侧过身面对武士，先把嘴角咬紧，汗从脸侧往下走；她把一只手松抬在肩后，让沾着不适触感的手远离衣料，另一只手落到腰旁。内心判断往下发展时，压紧的眉头渐渐松开一点，眼睛却继续盯着对手；她把下巴抬起，肩背从疲惫的松垮里撑直，嘴角慢慢形成一点带把握的笑。','铅蓝云天在后方，米灰尘雾低低压在灰绿石铺地面上，推近后地面退出。','上方云天冷白漫射，烟囱残基侧稍亮，空地弱中性补光。','一口长呼气逐渐放缓，发束擦过护件，对手方向砂粒仍在落地。',ja=['それにしても…刀を持っていた時より、ずっと戦いやすい…！','このままなら、勝てるかも？'],tone='内心先回顾判断，再带出谨慎希望，嘴不念内心。',kind='mixed',phase='state',node={'青.阶段':'认为现形后更好对付、重新生出胜算'},card={'opening':'嫌恶刚退，疲惫还在，注意转回如何获胜。','beats':['手离衣料、压眉咬嘴角','想通现形更好对付后撑肩抬下巴'],'coupling':'表情出现希望，但视线仍守住对手。','landing':'身体恢复迎战的主动。'})
